import { useEffect, useMemo, useRef, useState } from "react";
import { useLocation } from "wouter";
import { ArrowLeft, ArrowRight, Building2, CalendarDays, Check, ChevronDown, FileText, HardHat, ImagePlus, KeyRound, MapPin, Phone, Search, ShieldCheck, Trash2, Upload, Users, X } from "lucide-react";
import GlobalCityPicker from "@/components/GlobalCityPicker";
import { useAppStore } from "@/store/AppStoreContext";
import { useToast } from "@/hooks/use-toast";

const BG = "#040b14", CARD = "#111923", PANEL = "#182231", LINE = "rgba(255,255,255,.1)", TEXT = "#f5f5f5", DIM = "#929aa5", GOLD = "#f0b90b", GREEN = "#0ecb81";
const AMENITIES = ["24/7 Security", "Gated Community", "Parking Space", "Fiber Internet", "Backup Generator", "Water Filtration"];
const PROPERTY_TYPES = ["House", "Plot", "Commercial", "Apartment", "Villa", "Office"];
const PROPERTY_UNITS = ["Marla", "Kanal", "Sq. Ft."];

type CategoryId = "sale" | "rent" | "booking" | "materials" | "service" | "developer";
type ImageItem = { url: string; name: string };
type FormState = Record<string, string | string[]>;

const CATEGORIES: { id: CategoryId; label: string; description: string; icon: any; color: string }[] = [
  { id: "sale", label: "Sell Property", description: "Plots, houses, commercial properties", icon: Building2, color: GREEN },
  { id: "rent", label: "Rent Property", description: "Residential and commercial leases", icon: KeyRound, color: "#60a5fa" },
  { id: "booking", label: "Hotel & Villa Booking", description: "Stays, villas and daily bookings", icon: CalendarDays, color: "#a78bfa" },
  { id: "materials", label: "Construction & Materials", description: "Bricks, cement, tiles and fittings", icon: HardHat, color: "#f97316" },
  { id: "service", label: "Register Service / Trade", description: "Tradespeople and contractors", icon: Users, color: "#06b6d4" },
  { id: "developer", label: "Developer / Megaproject", description: "Off-plan and installment projects", icon: ShieldCheck, color: GOLD },
];

const emptyForm = (): FormState => ({ title: "", type: "House", purpose: "For Sale", city: "Lahore", area: "", amount: "", size: "", unit: "Marla", amenities: [], description: "", bookingType: "Villa", guests: "", checkIn: "15:00", checkOut: "11:00", productCategory: "Cement & Concrete", materialSubtype: "Cement & Concrete", materialUnit: "Per Bag", brand: "", moq: "", deliveryArea: "", deliveryAreas: [], deliveryMode: "Delivery Available", deliveryTime: "24-48 Hours", qualityTag: "", technicalSpecs: "", stock: "", businessName: "", tradeType: "Electrician", serviceArea: "", serviceCities: [], operationalAreas: "", experience: "", contact: "", pricingModel: "Fixed Fee Per Job", emergencyAvailable: "false", certification: "", projectName: "", developerName: "", projectType: "Mixed-Use Highrise", approvalStatus: "LDA / CDA / KDA Approved", downPayment: "", installment: "", tenure: "4 Years Plan", possession: "", possessionDate: "", inventoryTypes: [], brochure: "", deposit: "", advanceRent: "1 Month", leaseDuration: "1 Year Contract", furnishing: "Unfurnished", tenants: [], utilities: [], bedrooms: "1", baths: "1", cleaningFee: "", securityDeposit: "", minStay: "1 Night", cancellation: "Flexible - Full refund 24h prior", bookingAmenities: [], houseRules: [], coverIndex: "0", address: "", mapPin: "" });

const inputStyle: React.CSSProperties = { width: "100%", boxSizing: "border-box", padding: "12px 13px", borderRadius: 11, border: `1px solid ${LINE}`, background: PANEL, color: TEXT, outline: 0, fontSize: 13, fontFamily: "inherit" };
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label style={{ display: "grid", gap: 7, color: DIM, fontSize: 11, fontWeight: 700 }}>{label}{children}</label>; }
function TextInput({ value, onChange, placeholder, type = "text" }: { value: string; onChange: (v: string) => void; placeholder?: string; type?: string }) { return <input type={type} value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} style={inputStyle} />; }
function SelectInput({ value, onChange, options }: { value: string; onChange: (v: string) => void; options: string[] }) { return <select value={value} onChange={e => onChange(e.target.value)} style={inputStyle}>{options.map(x => <option key={x}>{x}</option>)}</select>; }
function Counter({ value, onChange }: { value: string; onChange: (v: string) => void }) { const numeric = Math.max(0, Number(value || 0)); return <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, padding: "6px 8px", borderRadius: 11, border: `1px solid ${LINE}`, background: PANEL }}><button type="button" onClick={() => onChange(String(Math.max(0, numeric - 1)))} style={{ width: 31, height: 31, border: `1px solid ${LINE}`, borderRadius: 8, background: CARD, color: TEXT, fontSize: 18 }}>−</button><strong style={{ color: TEXT, fontSize: 14 }}>{numeric}</strong><button type="button" onClick={() => onChange(String(numeric + 1))} style={{ width: 31, height: 31, border: `1px solid ${GOLD}66`, borderRadius: 8, background: `${GOLD}16`, color: GOLD, fontSize: 18 }}>+</button></div>; }

export default function SellAssetWizard() {
  const [, navigate] = useLocation();
  const { addListing } = useAppStore();
  const { toast } = useToast();
  const fileRef = useRef<HTMLInputElement>(null);
  const brochureRef = useRef<HTMLInputElement>(null);
  const query = useMemo(() => new URLSearchParams(typeof window !== "undefined" ? window.location.search : ""), []);
  const initialCategory = query.get("category") === "services" ? "service" : query.get("category") === "megaproject" ? "developer" : query.get("category");
  const [category, setCategory] = useState<CategoryId | null>((initialCategory as CategoryId) || null);
  const [step, setStep] = useState(Number(query.get("step") || 1));
  const [form, setForm] = useState<FormState>(() => { const base = emptyForm(); try { return { ...base, ...(JSON.parse(localStorage.getItem("okzbyte-sell-form-v2") || "null") || {}) }; } catch { return base; } });
  const [images, setImages] = useState<ImageItem[]>([]);
  const [confirmed, setConfirmed] = useState(false);
  const [publishing, setPublishing] = useState(false);
  const selected = CATEGORIES.find(c => c.id === category);
  const isProperty = category === "sale" || category === "rent";
  const update = (key: string, value: string | string[]) => setForm(prev => ({ ...prev, [key]: value }));

  useEffect(() => { localStorage.setItem("okzbyte-sell-form-v2", JSON.stringify(form)); }, [form]);
  useEffect(() => { if (category) localStorage.setItem("okzbyte-sell-category", category); }, [category]);
  const setWizard = (nextStep: number) => { setStep(nextStep); const suffix = category ? `?category=${category}&step=${nextStep}` : ""; window.history.replaceState({}, "", `/market/sell${suffix}`); };
  const handleCategory = (id: CategoryId) => { setCategory(id); update("purpose", id === "rent" ? "For Rent" : "For Sale"); setWizard(2); };
  const handleFiles = (files: FileList | null) => { if (!files) return; const next = Array.from(files).slice(0, 8 - images.length).map(file => ({ url: URL.createObjectURL(file), name: file.name })); setImages(prev => [...prev, ...next]); };
  const removeImage = (index: number) => { URL.revokeObjectURL(images[index]?.url || ""); setImages(prev => prev.filter((_, i) => i !== index)); };
  const handleBrochure = (file: File | undefined) => { if (!file) return; update("brochure", file.name); };

  const requiredKeys = isProperty ? ["title", "city", "area", "amount"] : category === "booking" ? ["title", "city", "amount"] : category === "materials" ? ["title", "amount", "moq", "stock", "deliveryArea"] : category === "service" ? ["businessName", "tradeType", "amount", "serviceCities", "contact"] : ["projectName", "developerName", "area", "amount", "approvalStatus", "possessionDate"];
  const canReview = requiredKeys.every(key => String(form[key] || "").trim().length > 0);
  const title = isProperty ? String(form.title || "") : category === "service" ? String(form.businessName || "") : category === "developer" ? String(form.projectName || "") : String(form.title || "");
  const amount = String(form.amount || "").replace(/[^0-9]/g, "");

  const publish = () => { if (!confirmed || !canReview || publishing) return; setPublishing(true); const listing = { id: `P-${Date.now()}`, pair: "LISTING/PKR", title: title.trim(), price: `PKR ${Number(amount || 0).toLocaleString()}`, roi: category === "rent" ? "Rental listing" : category === "materials" ? "B2B material supply" : category === "service" ? "Professional service provider" : selected?.label || "Marketplace listing", category, type: category === "materials" ? "materials" : category === "service" ? "services" : category === "developer" ? "megaprojects" : category, location: String(form.serviceArea || form.operationalAreas || form.area || form.city || form.deliveryArea || "Marketplace"), images: images.map(i => i.url), metadata: form } as any; addListing(listing); setTimeout(() => { toast({ title: "Listing published successfully!", description: "Your listing is now available in OkzByte Marketplace." }); localStorage.removeItem("okzbyte-sell-form-v2"); navigate(category === "rent" ? "/market/properties?type=rent" : category === "booking" ? "/market/properties?type=booking" : category === "materials" ? "/market/properties?type=materials" : category === "service" ? "/market/properties?type=services" : category === "developer" ? "/market/properties?type=megaprojects" : "/market/properties?type=buy"); }, 600); };

  const propertyForm = <>
    <Card title="BASIC INFORMATION" badge={selected?.label}><Field label="Listing title"><TextInput value={String(form.title || "")} onChange={v => update("title", v)} placeholder="5 Marla Luxury Villa" /></Field><div style={twoCol}><Field label="Asset type"><SelectInput value={String(form.type)} onChange={v => update("type", v)} options={PROPERTY_TYPES} /></Field><Field label="Purpose"><SelectInput value={String(form.purpose)} onChange={v => update("purpose", v)} options={["For Sale", "For Rent"]} /></Field></div></Card>
    <Card title="LOCATION & PRICING"><div style={twoCol}><Field label="City"><CityPicker value={String(form.city || "")} onChange={v => update("city", v)} /></Field><Field label="Area / location"><TextInput value={String(form.area || "")} onChange={v => update("area", v)} placeholder="DHA Phase 6" /></Field></div><Field label={category === "rent" ? "Monthly rent (PKR)" : "Total price (PKR)"}><TextInput type="number" value={String(form.amount || "")} onChange={v => update("amount", v)} placeholder="28500000" /></Field><div style={twoCol}><Field label="Area size"><TextInput type="number" value={String(form.size || "")} onChange={v => update("size", v)} placeholder="5" /></Field><Field label="Unit"><SelectInput value={String(form.unit)} onChange={v => update("unit", v)} options={PROPERTY_UNITS} /></Field></div></Card>
    <MediaCard /><Card title="FEATURES & AMENITIES"><div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>{AMENITIES.map(item => { const selectedAmenity = Array.isArray(form.amenities) && form.amenities.includes(item); return <label key={item} style={{ display: "flex", alignItems: "center", gap: 8, padding: "10px 9px", borderRadius: 10, border: `1px solid ${selectedAmenity ? `${GREEN}88` : LINE}`, background: selectedAmenity ? `${GREEN}12` : PANEL, color: selectedAmenity ? TEXT : DIM, fontSize: 10, cursor: "pointer" }}><input type="checkbox" checked={selectedAmenity} onChange={e => update("amenities", selectedAmenity ? (form.amenities as string[]).filter(x => x !== item) : [...(form.amenities as string[]), item])} style={{ accentColor: GREEN }} />{item}</label>; })}</div></Card><Card title="DESCRIPTION"><Field label="Asset description"><textarea value={String(form.description || "")} onChange={e => update("description", e.target.value)} placeholder="Describe the asset, access, condition and key terms" rows={4} style={{ ...inputStyle, resize: "vertical" }} /></Field></Card>
  </>;
  const rentalForm = <><Card title="BASIC INFORMATION" badge="Rent Property"><Field label="Listing title"><TextInput value={String(form.title || "")} onChange={v => update("title", v)} placeholder="Furnished 2 Bed Apartment in DHA Phase 6" /></Field><Field label="Property sub-type"><SelectInput value={String(form.type || "Apartment / Flat")} onChange={v => update("type", v)} options={["Apartment / Flat", "House / Portion", "Commercial Space / Office", "Penthouse", "Room / Sharing"]} /></Field><Field label="Furnishing status"><div style={{ display: "flex", flexWrap: "wrap", gap: 7 }}>{["Unfurnished", "Semi-Furnished", "Fully Furnished"].map(option => <button type="button" key={option} onClick={() => update("furnishing", option)} style={{ padding: "9px 10px", borderRadius: 10, border: `1px solid ${form.furnishing === option ? `${GOLD}aa` : LINE}`, background: form.furnishing === option ? `${GOLD}18` : PANEL, color: form.furnishing === option ? GOLD : DIM, fontSize: 11, fontWeight: 800 }}>{option}</button>)}</div></Field></Card><Card title="RENTAL PRICING & LEASE TERMS"><div style={twoCol}><Field label="Monthly rent (PKR)"><TextInput type="number" value={String(form.amount || "")} onChange={v => update("amount", v)} placeholder="150000" /></Field><Field label="Security deposit (PKR)"><TextInput type="number" value={String(form.deposit || "")} onChange={v => update("deposit", v)} placeholder="300000" /></Field></div><div style={twoCol}><Field label="Advance rent required"><SelectInput value={String(form.advanceRent)} onChange={v => update("advanceRent", v)} options={["1 Month", "3 Months", "6 Months", "1 Year"]} /></Field><Field label="Lease duration"><SelectInput value={String(form.leaseDuration)} onChange={v => update("leaseDuration", v)} options={["6 Months Minimum", "1 Year Contract", "Flexible Short-Term"]} /></Field></div></Card><Card title="LOCATION & PROPERTY SPECS"><div style={twoCol}><Field label="City"><CityPicker value={String(form.city || "")} onChange={v => update("city", v)} /></Field><Field label="Area / location"><TextInput value={String(form.area || "")} onChange={v => update("area", v)} placeholder="DHA Phase 6" /></Field></div><div style={twoCol}><Field label="Area size"><TextInput type="number" value={String(form.size || "")} onChange={v => update("size", v)} placeholder="1200" /></Field><Field label="Unit"><SelectInput value={String(form.unit || "Sq. Ft.")} onChange={v => update("unit", v)} options={["Marla", "Sq. Ft.", "Kanal"]} /></Field></div><div style={twoCol}><Field label="Bedrooms"><Counter value={String(form.bedrooms || "1")} onChange={v => update("bedrooms", v)} /></Field><Field label="Bathrooms"><Counter value={String(form.baths || "1")} onChange={v => update("baths", v)} /></Field></div></Card><Card title="TENANT PREFERENCES & UTILITIES"><div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>{["Families Only", "Bachelor / Professionals Allowed", "Corporate Lease"].map(item => { const active = Array.isArray(form.tenants) && form.tenants.includes(item); return <label key={item} style={{ display: "flex", alignItems: "center", gap: 7, padding: 9, borderRadius: 10, border: `1px solid ${active ? `${GREEN}88` : LINE}`, background: active ? `${GREEN}12` : PANEL, color: active ? TEXT : DIM, fontSize: 10 }}><input type="checkbox" checked={active} onChange={() => update("tenants", active ? (form.tenants as string[]).filter(x => x !== item) : [...(form.tenants as string[]), item])} style={{ accentColor: GREEN }} />{item}</label>; })}{["Water Included", "Electricity Bill Separate", "Gas Connection Available", "Maintenance Fee Included"].map(item => { const active = Array.isArray(form.utilities) && form.utilities.includes(item); return <label key={item} style={{ display: "flex", alignItems: "center", gap: 7, padding: 9, borderRadius: 10, border: `1px solid ${active ? `${GREEN}88` : LINE}`, background: active ? `${GREEN}12` : PANEL, color: active ? TEXT : DIM, fontSize: 10 }}><input type="checkbox" checked={active} onChange={() => update("utilities", active ? (form.utilities as string[]).filter(x => x !== item) : [...(form.utilities as string[]), item])} style={{ accentColor: GREEN }} />{item}</label>; })}</div></Card><MediaCard /><Card title="DESCRIPTION"><Field label="Rental description"><textarea value={String(form.description || "")} onChange={e => update("description", e.target.value)} placeholder="Describe the property, lease terms, access, condition and tenant requirements" rows={4} style={{ ...inputStyle, resize: "vertical" }} /></Field></Card></>;
  const bookingAmenities = ["High-Speed Wi-Fi", "Private Swimming Pool", "Complimentary Breakfast", "Air Conditioning", "Generator Backup", "Free Parking", "BBQ Area", "Daily Housekeeping"];
  const bookingRules = ["No Smoking Indoors", "Pets Allowed", "No Parties/Events"];
  const bookingForm = <>
    <Card title="BASIC PROPERTY INFORMATION" badge="Hospitality"><Field label="Listing name"><TextInput value={String(form.title || "")} onChange={v => update("title", v)} placeholder="Executive Luxury Villa with Private Pool" /></Field><div style={twoCol}><Field label="Stay type"><SelectInput value={String(form.bookingType || "Private Villa")} onChange={v => update("bookingType", v)} options={["Private Villa", "Boutique Hotel Room", "Serviced Apartment", "Resort Suite", "Farmhouse"]} /></Field><Field label="Max guests"><Counter value={String(form.guests || "2")} onChange={v => update("guests", v)} /></Field></div></Card>
    <Card title="NIGHTLY PRICING & BOOKING TERMS"><div style={twoCol}><Field label="Price per night (PKR)"><TextInput type="number" value={String(form.amount || "")} onChange={v => update("amount", v)} placeholder="45000" /></Field><Field label="Cleaning / service fee"><TextInput type="number" value={String(form.cleaningFee || "")} onChange={v => update("cleaningFee", v)} placeholder="Optional" /></Field></div><Field label="Refundable security deposit (PKR)"><TextInput type="number" value={String(form.securityDeposit || "")} onChange={v => update("securityDeposit", v)} placeholder="100000" /></Field><div style={twoCol}><Field label="Minimum stay"><SelectInput value={String(form.minStay || "1 Night")} onChange={v => update("minStay", v)} options={["1 Night", "2 Nights", "3+ Nights"]} /></Field><Field label="Cancellation policy"><SelectInput value={String(form.cancellation || "Flexible - Full refund 24h prior")} onChange={v => update("cancellation", v)} options={["Flexible - Full refund 24h prior", "Moderate", "Non-Refundable"]} /></Field></div><div style={twoCol}><Field label="Check-in"><TextInput type="time" value={String(form.checkIn || "14:00")} onChange={v => update("checkIn", v)} /></Field><Field label="Check-out"><TextInput type="time" value={String(form.checkOut || "12:00")} onChange={v => update("checkOut", v)} /></Field></div></Card>
    <Card title="LOCATION & ACCESSIBILITY"><Field label="Destination city"><CityPicker value={String(form.city || "")} onChange={v => update("city", v)} /></Field><Field label="Address / area"><TextInput value={String(form.address || form.area || "")} onChange={v => { update("address", v); update("area", v); }} placeholder="Gulberg III, Lahore" /></Field><Field label="Exact location pin"><button type="button" onClick={() => update("mapPin", String(form.address || form.area || form.city || "Location selected"))} style={{ width: "100%", minHeight: 80, borderRadius: 12, border: `1px solid ${GOLD}55`, background: `${GOLD}10`, color: DIM, cursor: "pointer" }}><MapPin size={21} color={GOLD} /><div>{form.mapPin ? "Location pin selected" : "Tap to set location pin"}</div><small style={{ color: GOLD }}>{String(form.mapPin || form.address || form.city || "Map preview")}</small></button></Field></Card>
    <Card title="ROOMS & AMENITIES"><div style={twoCol}><Field label="Bedrooms"><Counter value={String(form.bedrooms || "3")} onChange={v => update("bedrooms", v)} /></Field><Field label="Bathrooms"><Counter value={String(form.baths || "3")} onChange={v => update("baths", v)} /></Field></div><div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginTop: 10 }}>{bookingAmenities.map(item => { const active = Array.isArray(form.bookingAmenities) && form.bookingAmenities.includes(item); return <label key={item} style={{ display: "flex", alignItems: "center", gap: 7, padding: 9, borderRadius: 10, border: `1px solid ${active ? `${GREEN}88` : LINE}`, background: active ? `${GREEN}12` : PANEL, color: active ? TEXT : DIM, fontSize: 10 }}><input type="checkbox" checked={active} onChange={() => update("bookingAmenities", active ? (form.bookingAmenities as string[]).filter(x => x !== item) : [...(form.bookingAmenities as string[]), item])} style={{ accentColor: GREEN }} />{item}</label>; })}</div></Card>
    <Card title="HOUSE RULES"><div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>{bookingRules.map(item => { const active = Array.isArray(form.houseRules) && form.houseRules.includes(item); return <label key={item} style={{ display: "flex", alignItems: "center", gap: 7, padding: 9, borderRadius: 10, border: `1px solid ${active ? `${GOLD}88` : LINE}`, background: active ? `${GOLD}12` : PANEL, color: active ? TEXT : DIM, fontSize: 10 }}><input type="checkbox" checked={active} onChange={() => update("houseRules", active ? (form.houseRules as string[]).filter(x => x !== item) : [...(form.houseRules as string[]), item])} style={{ accentColor: GOLD }} />{item}</label>; })}</div></Card>
    <Card title="MEDIA & PHOTOS"><label onClick={() => fileRef.current?.click()} style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, minHeight: 74, borderRadius: 12, border: `1px dashed ${GOLD}77`, background: `${GOLD}08`, color: GOLD, fontSize: 12, fontWeight: 800, cursor: "pointer" }}><ImagePlus size={17} /> Add stay photos</label>{images.length > 0 && <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 7, marginTop: 10 }}>{images.map((image, i) => <div key={`${image.name}-${i}`} style={{ position: "relative", aspectRatio: "1", overflow: "hidden", borderRadius: 9, background: PANEL, border: String(form.coverIndex || "0") === String(i) ? `2px solid ${GOLD}` : `1px solid ${LINE}` }}><img src={image.url} alt="Stay preview" style={{ width: "100%", height: "100%", objectFit: "cover" }} /><button type="button" onClick={() => update("coverIndex", String(i))} style={{ position: "absolute", left: 4, bottom: 4, padding: "4px 6px", border: 0, borderRadius: 6, background: String(form.coverIndex || "0") === String(i) ? GOLD : "rgba(0,0,0,.7)", color: String(form.coverIndex || "0") === String(i) ? BG : TEXT, fontSize: 8, fontWeight: 800 }}>{String(form.coverIndex || "0") === String(i) ? "Main photo" : "Set as main"}</button><button type="button" onClick={() => removeImage(i)} style={{ position: "absolute", top: 3, right: 3, width: 23, height: 23, display: "grid", placeItems: "center", border: 0, borderRadius: "50%", background: "rgba(0,0,0,.75)", color: TEXT }}><X size={12} /></button></div>)}</div>}</Card>
    <Card title="DESCRIPTION"><Field label="Stay description"><textarea value={String(form.description || "")} onChange={e => update("description", e.target.value)} placeholder="Describe the stay, guest experience, access and key terms" rows={4} style={{ ...inputStyle, resize: "vertical" }} /></Field></Card>
  </>
  const materialDeliveryAreas = ["Lahore", "Islamabad", "Karachi", "Punjab Wide", "Nationwide"];
  const materialForm = <><Card title="PRODUCT & CATEGORY DETAILS" badge="B2B Supply"><Field label="Product name"><TextInput value={String(form.title || "")} onChange={v => update("title", v)} placeholder="Grade A Portland Cement - 50kg Bag" /></Field><div style={twoCol}><Field label="Material sub-type"><SelectInput value={String(form.materialSubtype || "Cement & Concrete")} onChange={v => { update("materialSubtype", v); update("productCategory", v); }} options={["Cement & Concrete", "Steel & Rebar", "Bricks & Blocks", "Tiles & Flooring", "Sanitaryware & Plumbing", "Electrical & Cables", "Paints & Coatings"]} /></Field><Field label="Brand / manufacturer"><TextInput value={String(form.brand || "")} onChange={v => update("brand", v)} placeholder="Maple Leaf, Mughal Steel, Master Tiles" /></Field></div></Card><Card title="PRICING, QUANTITY & MINIMUM ORDER"><div style={twoCol}><Field label="Price per unit (PKR)"><TextInput type="number" value={String(form.amount || "")} onChange={v => update("amount", v)} placeholder="1350" /></Field><Field label="Measurement unit"><SelectInput value={String(form.materialUnit || "Per Bag")} onChange={v => update("materialUnit", v)} options={["Per Bag", "Per Ton", "Per Sq. Ft.", "Per Piece", "Per Meter", "Per Truckload"]} /></Field></div><div style={twoCol}><Field label="Minimum order quantity (MOQ)"><Counter value={String(form.moq || "0")} onChange={v => update("moq", v)} /></Field><Field label="Available stock quantity"><TextInput type="number" value={String(form.stock || "")} onChange={v => update("stock", v)} placeholder="5000" /></Field></div></Card><Card title="DELIVERY & SUPPLY LOGISTICS"><Field label="Delivery availability"><div style={{ display: "flex", flexWrap: "wrap", gap: 7 }}>{["Delivery Available", "Self-Pickup Only", "Both"].map(option => <button type="button" key={option} onClick={() => update("deliveryMode", option)} style={{ padding: "9px 10px", borderRadius: 10, border: `1px solid ${form.deliveryMode === option ? `${GOLD}aa` : LINE}`, background: form.deliveryMode === option ? `${GOLD}18` : PANEL, color: form.deliveryMode === option ? GOLD : DIM, fontSize: 11, fontWeight: 800 }}>{option}</button>)}</div></Field><Field label="Delivery coverage areas"><div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>{materialDeliveryAreas.map(area => { const active = Array.isArray(form.deliveryAreas) && form.deliveryAreas.includes(area); return <label key={area} style={{ display: "flex", alignItems: "center", gap: 7, padding: 9, borderRadius: 10, border: `1px solid ${active ? `${GREEN}88` : LINE}`, background: active ? `${GREEN}12` : PANEL, color: active ? TEXT : DIM, fontSize: 10, cursor: "pointer" }}><input type="checkbox" checked={active} onChange={() => { const next = active ? (form.deliveryAreas as string[]).filter(x => x !== area) : [...(form.deliveryAreas as string[]), area]; update("deliveryAreas", next); update("deliveryArea", next.join(", ")); }} style={{ accentColor: GREEN }} />{area}</label>; })}</div></Field><Field label="Estimated delivery time"><SelectInput value={String(form.deliveryTime || "24-48 Hours")} onChange={v => update("deliveryTime", v)} options={["Same Day", "24-48 Hours", "3-5 Days"]} /></Field></Card><Card title="SPECIFICATIONS & TECHNICAL DATA"><Field label="Grade / standard quality tag"><TextInput value={String(form.qualityTag || "")} onChange={v => update("qualityTag", v)} placeholder="ISO 9001 Certified / 500W Deformed Bars" /></Field><Field label="Description & technical specifications"><textarea value={String(form.technicalSpecs || form.description || "")} onChange={e => { update("technicalSpecs", e.target.value); update("description", e.target.value); }} placeholder="Add dimensions, weight, grade, packaging and recommended usage guidelines." rows={5} style={{ ...inputStyle, resize: "vertical" }} /></Field></Card><MediaCard label="PRODUCT PHOTOS" /></>;
  const serviceCities = ["Lahore", "Islamabad", "Karachi", "Rawalpindi"];
  const serviceTrades = ["Electrician", "Plumbing Services", "HVAC / AC Technician", "Interior Designer / Architect", "Painter & Woodwork", "General Contractor / Masonry", "Solar Installation"];
  const serviceForm = <><Card title="SERVICE PROVIDER PROFILE" badge="Professional registration"><Field label="Business / contractor name"><TextInput value={String(form.businessName || "")} onChange={v => update("businessName", v)} placeholder="Apex HVAC & Electrical Solutions" /></Field><div style={twoCol}><Field label="Primary trade category"><SelectInput value={String(form.tradeType || "Electrician")} onChange={v => update("tradeType", v)} options={serviceTrades} /></Field><Field label="Years of experience"><Counter value={String(form.experience || "0")} onChange={v => update("experience", v)} /></Field></div></Card><Card title="PRICING, VISITATION & RATE STRUCTURE"><div style={twoCol}><Field label="Inspection / visit fee (PKR)"><TextInput type="number" value={String(form.amount || "")} onChange={v => update("amount", v)} placeholder="1500" /></Field><Field label="Pricing model"><SelectInput value={String(form.pricingModel || "Fixed Fee Per Job")} onChange={v => update("pricingModel", v)} options={["Fixed Fee Per Job", "Hourly Rate", "Custom Quote / Free Inspection"]} /></Field></div><button type="button" aria-pressed={form.emergencyAvailable === "true"} onClick={() => update("emergencyAvailable", form.emergencyAvailable === "true" ? "false" : "true")} style={{ width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, padding: "11px 12px", borderRadius: 11, border: `1px solid ${form.emergencyAvailable === "true" ? `${GREEN}99` : LINE}`, background: form.emergencyAvailable === "true" ? `${GREEN}12` : PANEL, color: form.emergencyAvailable === "true" ? GREEN : DIM, fontSize: 11, fontWeight: 800, cursor: "pointer" }}><span>Available for emergency calls</span><span style={{ width: 34, height: 19, display: "flex", alignItems: "center", padding: 2, borderRadius: 20, background: form.emergencyAvailable === "true" ? GREEN : "#303844", justifyContent: form.emergencyAvailable === "true" ? "flex-end" : "flex-start" }}><span style={{ width: 15, height: 15, borderRadius: "50%", background: TEXT }} /></span></button></Card><Card title="SERVICE AREA & CONTACT"><Field label="Cities covered"><div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>{serviceCities.map(city => { const active = Array.isArray(form.serviceCities) && form.serviceCities.includes(city); return <label key={city} style={{ display: "flex", alignItems: "center", gap: 7, padding: 9, borderRadius: 10, border: `1px solid ${active ? `${GREEN}88` : LINE}`, background: active ? `${GREEN}12` : PANEL, color: active ? TEXT : DIM, fontSize: 10, cursor: "pointer" }}><input type="checkbox" checked={active} onChange={() => { const next = active ? (form.serviceCities as string[]).filter(x => x !== city) : [...(form.serviceCities as string[]), city]; update("serviceCities", next); update("serviceArea", next.join(", ")); }} style={{ accentColor: GREEN }} />{city}</label>; })}</div></Field><Field label="Operational areas / neighborhoods"><TextInput value={String(form.operationalAreas || "")} onChange={v => update("operationalAreas", v)} placeholder="DHA, Gulberg, Cantt" /></Field><Field label="Direct business WhatsApp / phone"><TextInput type="tel" value={String(form.contact || "")} onChange={v => update("contact", v)} placeholder="+92 300 0000000" /></Field></Card><Card title="PORTFOLIO, CREDENTIALS & MEDIA"><Field label="Certification / license tag"><TextInput value={String(form.certification || "")} onChange={v => update("certification", v)} placeholder="PEC Registered / Certified HVAC Technician" /></Field><MediaCard label="PORTFOLIO PHOTO UPLOADER" /><Field label="Service description"><textarea value={String(form.description || "")} onChange={e => update("description", e.target.value)} placeholder="Outline scope of work, warranty details, response time and team capacity." rows={5} style={{ ...inputStyle, resize: "vertical" }} /></Field></Card></>;
  const megaprojectInventory = ["1 Bed Apartments", "2 Bed Apartments", "Executive Penthouse", "Commercial Shops"];
  const developerForm = <><Card title="DEVELOPMENT & DEVELOPER DETAILS" badge="Institutional project"><Field label="Project title"><TextInput value={String(form.projectName || "")} onChange={v => update("projectName", v)} placeholder="Sovereign Heights & Luxury Towers" /></Field><div style={twoCol}><Field label="Developer / company name"><TextInput value={String(form.developerName || "")} onChange={v => update("developerName", v)} placeholder="Orakzai Group Developments" /></Field><Field label="Project type"><SelectInput value={String(form.projectType || "Mixed-Use Highrise")} onChange={v => update("projectType", v)} options={["Mixed-Use Highrise", "Gated Community", "Commercial Mall", "Luxury Residential Complex"]} /></Field></div><Field label="Approval status"><SelectInput value={String(form.approvalStatus || "LDA / CDA / KDA Approved")} onChange={v => update("approvalStatus", v)} options={["LDA / CDA / KDA Approved", "Approval Under Process", "NOC Verified"]} /></Field></Card><Card title="INSTALLMENT PLAN & PRICING"><div style={twoCol}><Field label="Starting price (PKR)"><TextInput type="number" value={String(form.amount || "")} onChange={v => update("amount", v)} placeholder="12000000" /></Field><Field label="Down payment requirement"><TextInput value={String(form.downPayment || "")} onChange={v => update("downPayment", v)} placeholder="10% Down Payment" /></Field></div><div style={twoCol}><Field label="Monthly / quarterly installment (PKR)"><TextInput type="number" value={String(form.installment || "")} onChange={v => update("installment", v)} placeholder="45000" /></Field><Field label="Total payment tenure"><SelectInput value={String(form.tenure || "4 Years Plan")} onChange={v => update("tenure", v)} options={["3 Years Plan", "4 Years Plan", "5 Years Easy Installments"]} /></Field></div><Field label="Expected possession date"><TextInput type="month" value={String(form.possessionDate || "")} onChange={v => update("possessionDate", v)} /></Field></Card><Card title="LOCATION & UNITS AVAILABLE"><div style={twoCol}><Field label="City"><CityPicker value={String(form.city || "")} onChange={v => update("city", v)} /></Field><Field label="Location area / address"><TextInput value={String(form.area || "")} onChange={v => update("area", v)} placeholder="Blue Area, Islamabad" /></Field></div><Field label="Available inventory types"><div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>{megaprojectInventory.map(item => { const active = Array.isArray(form.inventoryTypes) && form.inventoryTypes.includes(item); return <label key={item} style={{ display: "flex", alignItems: "center", gap: 7, padding: 9, borderRadius: 10, border: `1px solid ${active ? `${GOLD}99` : LINE}`, background: active ? `${GOLD}12` : PANEL, color: active ? TEXT : DIM, fontSize: 10, cursor: "pointer" }}><input type="checkbox" checked={active} onChange={() => update("inventoryTypes", active ? (form.inventoryTypes as string[]).filter(x => x !== item) : [...(form.inventoryTypes as string[]), item])} style={{ accentColor: GOLD }} />{item}</label>; })}</div></Field></Card><Card title="MEDIA, BROCHURE & SPECIFICATIONS"><MediaCard label="HIGH-RES RENDERS & SITE PROGRESS" /><Field label="Project PDF brochure"><button type="button" onClick={() => brochureRef.current?.click()} style={{ width: "100%", display: "flex", alignItems: "center", gap: 8, padding: "12px 13px", borderRadius: 11, border: `1px dashed ${GOLD}77`, background: `${GOLD}08`, color: form.brochure ? GREEN : GOLD, fontSize: 11, fontWeight: 800, cursor: "pointer" }}><FileText size={16} />{form.brochure ? String(form.brochure) : "Upload project PDF brochure"}</button></Field><Field label="Project overview & master plan description"><textarea value={String(form.description || "")} onChange={e => update("description", e.target.value)} placeholder="Outline the master plan, amenities, development phases, infrastructure, unit mix, approvals and investor terms." rows={6} style={{ ...inputStyle, resize: "vertical" }} /></Field></Card></>;

  function CityPicker({ value, onChange }: { value: string; onChange: (value: string) => void }) { return <GlobalCityPicker value={value} onChange={(next) => onChange(next)} placeholder="Search or select a city" />; }

  function MediaCard({ label = "MEDIA & PHOTOS" }: { label?: string }) { return <Card title={label}><div onDragOver={e => e.preventDefault()} onDrop={e => { e.preventDefault(); handleFiles(e.dataTransfer.files); }} onClick={() => fileRef.current?.click()} style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 6, minHeight: 86, borderRadius: 12, border: `1px dashed ${GOLD}77`, background: `${GOLD}08`, color: GOLD, fontSize: 12, fontWeight: 800, cursor: "pointer", textAlign: "center" }}><Upload size={17} /><span>Drop files here or browse photos</span><small style={{ color: DIM, fontSize: 10, fontWeight: 600 }}>Up to 8 high-resolution images</small></div>{images.length > 0 && <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 7, marginTop: 10 }}>{images.map((image, i) => <div key={`${image.name}-${i}`} style={{ position: "relative", aspectRatio: "1", overflow: "hidden", borderRadius: 9, background: PANEL }}><img src={image.url} alt="Listing preview" style={{ width: "100%", height: "100%", objectFit: "cover" }} /><button type="button" onClick={e => { e.stopPropagation(); removeImage(i); }} aria-label="Remove photo" style={{ position: "absolute", top: 3, right: 3, width: 23, height: 23, display: "grid", placeItems: "center", border: 0, borderRadius: "50%", background: "rgba(0,0,0,.75)", color: TEXT }}><X size={12} /></button></div>)}</div>}</Card>; }
  function Card({ title: cardTitle, badge, children }: { title: string; badge?: string; children: React.ReactNode }) { return <div style={{ padding: 15, borderRadius: 16, border: `1px solid ${LINE}`, background: CARD }}><div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, marginBottom: 14 }}><span style={{ color: GOLD, fontSize: 10, fontWeight: 900, letterSpacing: ".12em" }}>{cardTitle}</span>{badge && <span style={{ color: GREEN, fontSize: 10, fontWeight: 800 }}>{badge}</span>}</div>{children}</div>; }

  const details = category === "rent" ? rentalForm : category === "sale" ? propertyForm : category === "booking" ? bookingForm : category === "materials" ? materialForm : category === "service" ? serviceForm : developerForm;
  return <div style={{ minHeight: "100dvh", paddingBottom: "calc(96px + env(safe-area-inset-bottom))", background: BG, color: TEXT, fontFamily: "-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif", WebkitFontSmoothing: "antialiased" }}>
    <input ref={fileRef} type="file" accept="image/*" multiple onChange={e => handleFiles(e.target.files)} style={{ display: "none" }} /><input ref={brochureRef} type="file" accept="application/pdf,.pdf" onChange={e => handleBrochure(e.target.files?.[0])} style={{ display: "none" }} />
    <header style={{ position: "sticky", top: 0, zIndex: 20, height: 58, display: "flex", alignItems: "center", gap: 10, padding: "0 14px", background: "rgba(4,11,20,.96)", borderBottom: `1px solid ${LINE}`, backdropFilter: "blur(16px)" }}><button onClick={() => step > 1 ? setWizard(step - 1) : navigate("/")} aria-label="Back" style={{ border: 0, background: "transparent", color: DIM, padding: 8 }}><ArrowLeft size={20} /></button><div style={{ minWidth: 0, flex: 1 }}><div style={{ color: GOLD, fontSize: 10, fontWeight: 900, letterSpacing: ".13em" }}>MARKETPLACE</div><strong style={{ display: "block", marginTop: 3, fontSize: 15 }}>List &amp; Sell Asset</strong></div><span style={{ color: DIM, fontSize: 11 }}>{step}/3</span></header>
    <main style={{ maxWidth: 680, margin: "0 auto", padding: "18px 14px" }}><div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 5, marginBottom: 20 }}>{["Category", "Details", "Review"].map((label, i) => <div key={label}><div style={{ height: 4, borderRadius: 8, background: step > i ? GOLD : "rgba(255,255,255,.12)" }} /><span style={{ display: "block", marginTop: 6, color: step === i + 1 ? TEXT : DIM, fontSize: 10, fontWeight: 700 }}>{label}</span></div>)}</div><div style={{ marginBottom: 18 }}><h1 style={{ margin: 0, fontSize: 24, lineHeight: 1.15, letterSpacing: "-.02em" }}>{step === 1 ? "Choose listing type" : step === 2 ? "Listing information" : "Review listing"}</h1><p style={{ margin: "7px 0 0", color: DIM, fontSize: 12, lineHeight: 1.5 }}>{step === 1 ? "Select the category that best matches your asset." : step === 2 ? "Enter clear details so buyers can evaluate the listing." : "Check the details before publishing to OkzByte Marketplace."}</p></div>
      {step === 1 && <section style={{ display: "grid", gridTemplateColumns: "repeat(2,minmax(0,1fr))", gap: 10 }}>{CATEGORIES.map(item => { const Icon = item.icon; return <button key={item.id} onClick={() => handleCategory(item.id)} style={{ minHeight: 144, padding: 14, display: "flex", flexDirection: "column", alignItems: "flex-start", justifyContent: "space-between", gap: 16, textAlign: "left", borderRadius: 16, border: `1px solid ${LINE}`, background: CARD, color: TEXT, cursor: "pointer" }}><span style={{ width: 40, height: 40, display: "grid", placeItems: "center", borderRadius: 12, color: item.color, background: `${item.color}18` }}><Icon size={21} /></span><span><strong style={{ display: "block", fontSize: 13, lineHeight: 1.3 }}>{item.label}</strong><small style={{ display: "block", marginTop: 6, color: DIM, fontSize: 10, lineHeight: 1.35 }}>{item.description}</small></span></button>; })}</section>}
      {step === 2 && <section style={{ display: "grid", gap: 12 }}>{details}<button disabled={!canReview} onClick={() => setWizard(3)} style={{ width: "100%", padding: 14, border: 0, borderRadius: 13, background: canReview ? GOLD : "#303844", color: canReview ? BG : DIM, fontSize: 13, fontWeight: 900, cursor: canReview ? "pointer" : "not-allowed" }}>Review listing <ArrowRight size={16} style={{ verticalAlign: "middle", marginLeft: 5 }} /></button>{!canReview && <p style={{ margin: 0, color: DIM, textAlign: "center", fontSize: 10 }}>Complete the highlighted required fields to continue.</p>}</section>}
      {step === 3 && <section style={{ display: "grid", gap: 13 }}><div style={{ padding: 16, borderRadius: 17, border: `1px solid ${GOLD}66`, background: "linear-gradient(135deg,#151d28,#101720)" }}><div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 10 }}><div><span style={{ color: GOLD, fontSize: 10, fontWeight: 900, letterSpacing: ".12em" }}>MARKETPLACE PREVIEW</span><h2 style={{ margin: "7px 0 0", fontSize: 20, lineHeight: 1.2 }}>{title || "Untitled listing"}</h2></div><span style={{ padding: "5px 8px", borderRadius: 7, color: GREEN, background: `${GREEN}18`, fontSize: 9, fontWeight: 900 }}>READY TO PUBLISH</span></div><div style={{ display: "flex", alignItems: "center", gap: 5, marginTop: 10, color: DIM, fontSize: 11 }}><MapPin size={13} color={GOLD} />{String(form.area || form.serviceArea || form.deliveryArea || form.city || "Marketplace")}</div>{images.length > 0 && <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 6, marginTop: 14 }}>{images.slice(0, 6).map((image, i) => <img key={i} src={image.url} alt="Preview" style={{ width: "100%", height: 90, objectFit: "cover", borderRadius: 9 }} />)}</div>}<div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 1, marginTop: 14, overflow: "hidden", borderRadius: 10, background: LINE }}><div style={{ padding: 11, background: CARD }}><span style={{ display: "block", color: DIM, fontSize: 9 }}>ASKING</span><strong style={{ display: "block", marginTop: 5, color: GOLD, fontSize: 14 }}>PKR {Number(amount || 0).toLocaleString()}</strong></div><div style={{ padding: 11, background: CARD }}><span style={{ display: "block", color: DIM, fontSize: 9 }}>CATEGORY</span><strong style={{ display: "block", marginTop: 5, fontSize: 12 }}>{selected?.label}</strong></div><div style={{ padding: 11, background: CARD }}><span style={{ display: "block", color: DIM, fontSize: 9 }}>STATUS</span><strong style={{ display: "block", marginTop: 5, color: GREEN, fontSize: 12 }}>Verified review</strong></div></div><p style={{ margin: "13px 0 0", color: DIM, fontSize: 12, lineHeight: 1.55 }}>{String(form.description || "Professional listing submitted for marketplace review.")}</p>{category === "booking" && <div style={{ marginTop: 13, padding: 12, borderRadius: 11, background: PANEL, border: `1px solid ${LINE}` }}><div style={{ color: GOLD, fontSize: 9, fontWeight: 900, letterSpacing: ".12em", marginBottom: 9 }}>STAY SUMMARY</div><div style={{ display: "flex", flexWrap: "wrap", gap: 6, color: TEXT, fontSize: 11 }}><span style={{ padding: "5px 7px", borderRadius: 7, background: `${GOLD}18`, color: GOLD }}>PKR {Number(amount || 0).toLocaleString()} / night</span><span style={{ padding: "5px 7px", borderRadius: 7, background: `${GREEN}18`, color: GREEN }}>{String(form.bedrooms || 0)} Beds · {String(form.baths || 0)} Baths · {String(form.guests || 0)} Guests max</span></div><div style={{ marginTop: 8, color: DIM, fontSize: 10 }}>Stay type: {String(form.bookingType || "Private Villa")} · Minimum: {String(form.minStay || "1 Night")} · Cancellation: {String(form.cancellation || "Flexible")}</div><div style={{ marginTop: 8, color: DIM, fontSize: 10 }}>Amenities: {Array.isArray(form.bookingAmenities) && form.bookingAmenities.length ? form.bookingAmenities.join(" · ") : "Not specified"}</div></div>}{category === "materials" && <div style={{ marginTop: 13, padding: 13, borderRadius: 12, background: PANEL, border: `1px solid ${LINE}` }}><div style={{ color: GOLD, fontSize: 9, fontWeight: 900, letterSpacing: ".12em", marginBottom: 10 }}>B2B MATERIAL SUMMARY</div><div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 10 }}><strong style={{ color: GOLD, fontSize: 20 }}>PKR {Number(amount || 0).toLocaleString()}</strong><span style={{ color: DIM, fontSize: 10 }}>{String(form.materialUnit || "Per Unit")}</span></div><div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 10 }}><span style={{ padding: "5px 7px", borderRadius: 7, background: `${GOLD}18`, color: GOLD, fontSize: 10 }}>MOQ: {String(form.moq || 0)} {String(form.materialUnit || "units").replace(/^Per /, "")}</span><span style={{ padding: "5px 7px", borderRadius: 7, background: `${GREEN}18`, color: GREEN, fontSize: 10 }}>In Stock: {Number(form.stock || 0).toLocaleString()}</span><span style={{ padding: "5px 7px", borderRadius: 7, background: `${GREEN}18`, color: GREEN, fontSize: 10 }}>{String(form.deliveryMode || "Delivery Available")}</span></div><div style={{ marginTop: 9, color: DIM, fontSize: 10 }}>Delivery availability: {String(form.deliveryArea || "Coverage to be confirmed")} · {String(form.deliveryTime || "24-48 Hours")}</div><div style={{ marginTop: 6, color: DIM, fontSize: 10 }}>Category: {String(form.materialSubtype || form.productCategory || "Construction material")} · Brand: {String(form.brand || "Manufacturer not specified")}</div></div>}{category === "service" && <div style={{ marginTop: 13, padding: 13, borderRadius: 12, background: PANEL, border: `1px solid ${LINE}` }}><div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 10 }}><div><div style={{ color: GOLD, fontSize: 9, fontWeight: 900, letterSpacing: ".12em", marginBottom: 8 }}>VERIFIED PROFESSIONAL SERVICE</div><strong style={{ display: "block", color: TEXT, fontSize: 18 }}>{title || "Professional service provider"}</strong><span style={{ display: "inline-flex", marginTop: 5, padding: "5px 8px", borderRadius: 7, background: `${GREEN}18`, color: GREEN, fontSize: 10, fontWeight: 800 }}>{String(form.tradeType || "Trade specialist")}</span></div><ShieldCheck size={22} color={GREEN} /></div><div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 12 }}><span style={{ padding: "5px 7px", borderRadius: 7, background: `${GOLD}18`, color: GOLD, fontSize: 10 }}>PKR {Number(amount || 0).toLocaleString()} {String(form.pricingModel || "Visit Fee") === "Custom Quote / Free Inspection" ? "· Free quote" : "visit fee"}</span><span style={{ padding: "5px 7px", borderRadius: 7, background: `${GREEN}18`, color: GREEN, fontSize: 10 }}>{String(form.experience || 0)}+ Yrs Exp</span><span style={{ padding: "5px 7px", borderRadius: 7, background: `${GREEN}18`, color: GREEN, fontSize: 10 }}>{String(form.certification || "Verified provider")}</span></div><div style={{ marginTop: 10, color: DIM, fontSize: 10 }}>Coverage: {String(form.serviceCities || "Cities to be confirmed")} · {String(form.operationalAreas || "Operational areas to be confirmed")}</div><div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginTop: 12 }}><a href={`tel:${String(form.contact || "")}`} style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 5, padding: "9px 8px", borderRadius: 9, background: `${GREEN}18`, color: GREEN, fontSize: 10, fontWeight: 900, textDecoration: "none" }}><Phone size={13} />Call now</a><a href={`https://wa.me/${String(form.contact || "").replace(/[^0-9]/g, "")}`} target="_blank" rel="noreferrer" style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 5, padding: "9px 8px", borderRadius: 9, background: PANEL, border: `1px solid ${LINE}`, color: TEXT, fontSize: 10, fontWeight: 900, textDecoration: "none" }}>WhatsApp direct</a></div></div>}{category === "developer" && <div style={{ marginTop: 13, padding: 13, borderRadius: 12, background: PANEL, border: `1px solid ${LINE}` }}><div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 10 }}><div><div style={{ color: GOLD, fontSize: 9, fontWeight: 900, letterSpacing: ".12em", marginBottom: 8 }}>INSTITUTIONAL PROJECT SHOWCASE</div><strong style={{ display: "block", color: TEXT, fontSize: 18 }}>{title || "Untitled megaproject"}</strong><span style={{ display: "inline-flex", marginTop: 5, padding: "5px 8px", borderRadius: 7, background: `${GOLD}18`, color: GOLD, fontSize: 10, fontWeight: 800 }}>{String(form.developerName || "Developer company")}</span></div><ShieldCheck size={22} color={GREEN} /></div><div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 12 }}><span style={{ padding: "5px 7px", borderRadius: 7, background: `${GREEN}18`, color: GREEN, fontSize: 10 }}>{String(form.approvalStatus || "Approval pending")}</span><span style={{ padding: "5px 7px", borderRadius: 7, background: `${GOLD}18`, color: GOLD, fontSize: 10 }}>From PKR {Number(amount || 0).toLocaleString()}</span><span style={{ padding: "5px 7px", borderRadius: 7, background: `${GOLD}18`, color: GOLD, fontSize: 10 }}>{String(form.tenure || "Easy installments")}</span></div><div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginTop: 11, color: DIM, fontSize: 10 }}><span>Installment: PKR {Number(form.installment || 0).toLocaleString()} / month</span><span>Down payment: {String(form.downPayment || "To be confirmed")}</span><span>Possession: {String(form.possessionDate || "Timeline to be confirmed")}</span><span>Location: {String(form.area || form.city || "Location to be confirmed")}</span></div><div style={{ marginTop: 10, color: DIM, fontSize: 10 }}>Inventory: {Array.isArray(form.inventoryTypes) && form.inventoryTypes.length ? form.inventoryTypes.join(" · ") : "Inventory to be confirmed"}</div>{form.brochure && <div style={{ marginTop: 8, color: GREEN, fontSize: 10 }}>Brochure attached: {String(form.brochure)}</div>}</div>}{category === "developer" && <div style={{ marginTop: 13, padding: 13, borderRadius: 12, background: PANEL, border: `1px solid ${LINE}` }}><div style={{ color: GOLD, fontSize: 9, fontWeight: 900, letterSpacing: ".12em", marginBottom: 10 }}>PROJECT REGISTRATION SUMMARY</div><div style={{ color: DIM, fontSize: 10 }}>Type: {String(form.projectType || "Mixed-Use Highrise")} · City: {String(form.city || "Not specified")} · Approval: {String(form.approvalStatus || "Under review")}</div></div>}{category === "service" && <div style={{ marginTop: 13, padding: 13, borderRadius: 12, background: PANEL, border: `1px solid ${LINE}` }}><div style={{ color: GOLD, fontSize: 9, fontWeight: 900, letterSpacing: ".12em", marginBottom: 10 }}>SERVICE REGISTRATION SUMMARY</div><div style={{ display: "flex", flexWrap: "wrap", gap: 6, color: DIM, fontSize: 10 }}><span>Pricing: {String(form.pricingModel || "Fixed Fee Per Job")}</span><span>·</span><span>{form.emergencyAvailable === "true" ? "Emergency calls available" : "Standard availability"}</span></div></div>}</div><div style={{ padding: 15, borderRadius: 16, background: CARD, border: `1px solid ${LINE}` }}><div style={{ color: GOLD, fontSize: 10, fontWeight: 900, letterSpacing: ".12em", marginBottom: 12 }}>PUBLISH CHECKLIST</div>{["Listing information entered", `${images.length} media file${images.length === 1 ? "" : "s"} attached`, "Marketplace review required"].map(item => <div key={item} style={{ display: "flex", alignItems: "center", gap: 9, padding: "8px 0", color: DIM, fontSize: 11, borderBottom: `1px solid ${LINE}` }}><Check size={14} color={GREEN} />{item}</div>)}<label style={{ display: "flex", alignItems: "flex-start", gap: 9, marginTop: 14, color: TEXT, fontSize: 11, lineHeight: 1.4, cursor: "pointer" }}><input type="checkbox" checked={confirmed} onChange={e => setConfirmed(e.target.checked)} style={{ accentColor: GOLD, marginTop: 2 }} />I confirm that I am the authorized owner or agent for this listing.</label></div><div style={{ display: "grid", gridTemplateColumns: "1fr 1.4fr", gap: 10 }}><button onClick={() => setWizard(2)} style={{ padding: 14, borderRadius: 13, border: `1px solid ${LINE}`, background: PANEL, color: TEXT, fontSize: 12, fontWeight: 800 }}>Edit details</button><button disabled={!confirmed || publishing} onClick={publish} style={{ padding: 14, border: 0, borderRadius: 13, background: confirmed && !publishing ? GOLD : "#303844", color: confirmed && !publishing ? BG : DIM, fontSize: 12, fontWeight: 900 }}>{publishing ? "Publishing…" : category === "materials" ? "Publish material listing" : category === "service" ? "Register & publish service" : category === "developer" ? "Publish megaproject live" : category === "booking" ? "Publish stay listing live" : "Publish listing live"}</button></div></section>}
    </main>
  </div>;
}

const twoCol: React.CSSProperties = { display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 };
const threeCol: React.CSSProperties = { display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 8 };
